let spData=null,spCompare=new Set(),spPlans=[],spEpoch=0;
const spLink=(id)=>'#self-paced/'+id;
const spCard=p=>`<article class="card prose"><p class="eyebrow">#${p.id} · ${esc(p.type)}</p><h2><a href="${spLink(p.id)}">${esc(p.title)}</a></h2><p>${esc(p.summary)}</p><p>${esc(p.level)} · ${p.hours} estimated effort hours · ${p.courseCount} course${p.courseCount===1?'':'s'} · ${p.sequentialWeeks} weeks sequentially (10/course)</p><p>${esc(p.skills.join(' · '))}</p><p>${esc(p.credential)} · Not issued</p><p>Paid sandbox model · Price pending</p><p>${p.transfer.length?'Proposed mappings: '+p.transfer.map(t=>'#'+t.to).join(', ')+'. Approval required.':'No approved transfer.'}</p><label><input type="checkbox" data-sp-compare="${p.id}" ${spCompare.has(p.id)?'checked':''}> Compare</label><a class="button secondary" href="${spLink(p.id)}">View curriculum</a></article>`;
function spHub(){return heading('Agentic AI courses & certificates','Scholarion Academy · Self-paced learning, from foundations to accountable agents')+`<section class="card prose"><p>Explore machine learning, language systems, retrieval and tool-using agents. These eleven offerings are draft curricula awaiting academic and technical review.</p><p>Paid per course or credential in sandbox. Prices and checkout are not configured. Certificates recognize program completion; professional competency certification is not offered.</p><div class="row wrap"><a href="#catalog">All programs</a><a href="#consolidation">Program mapping register</a><a href="#self-paced-pathways">Self-paced pathways and mappings</a></div></section><section class="card"><h2>Find your path</h2><div class="filterbar"><label>Search<input id="sp-search" type="search"></label><label>Product type<select id="sp-type"><option>All</option>${[...new Set(spData.offerings.map(p=>p.type))].map(t=>`<option>${esc(t)}</option>`).join('')}</select></label><label>Level<select id="sp-level"><option>All</option><option>Foundational</option><option>Intermediate</option><option>Advanced</option></select></label><label>Coding<select id="sp-coding"><option>All</option><option>Python</option><option>No code</option></select></label><label>Skill<select id="sp-skill"><option>All</option>${[...new Set(spData.offerings.flatMap(p=>p.skills))].sort().map(s=>`<option>${esc(s)}</option>`).join('')}</select></label><label>Estimated effort<select id="sp-hours"><option value="0">All</option><option value="16">Up to 16 hours</option><option value="60">Up to 60 hours</option></select></label></div><p>All offerings: self-paced · paid sandbox access model · ten-week course schedules.</p><p id="sp-count" role="status"></p><button class="button secondary" id="sp-compare">Compare selected (up to 3)</button></section><div class="catalog-grid" id="sp-results">${spData.offerings.map(spCard).join('')}</div><section class="card prose"><h2>Start here</h2><p>${[32,37,34].map(n=>`<a href="${spLink(n)}">#${n} ${esc(spData.offerings.find(p=>p.id===n).title)}</a>`).join(' · ')}</p><h2>Which path is right for me?</h2><form id="sp-recommend"><label>Your goal<select name="goal"><option value="patterns">Understand agent patterns</option><option value="foundations">Build ML foundations</option><option value="python">Build Python agents</option><option value="leaders">Lead adoption without coding</option><option value="rag">Build retrieval applications</option></select></label><button class="button">Find a starting point</button></form><p id="sp-recommend-result" role="status"></p><h2>For teams</h2><p>Use the authenticated Support module to request a discussion of team delivery. No seats or invoice will be created.</p><a href="#help">Open support</a><h2>Common questions</h2><details><summary>Can I enroll or pay now?</summary><p>No. Paid sandbox access is selected, but prices, payment policies and the provider remain unconfigured.</p></details><details><summary>Do these offerings automatically waive live modules?</summary><p>No. Mappings are proposals until assessed equivalence and academic approval are recorded.</p></details><details><summary>Are badges verifiable?</summary><p>Existing badge artwork is a preview. Signed issuance and public verification remain unavailable.</p></details><details><summary>How long is a course?</summary><p>Every course uses ten suggested weeks. Effort estimates differ from elapsed duration. A bundle contains multiple courses.</p></details></section>`;}
function spProduct(p){return `<a href="#self-paced">← Self-paced catalog</a>`+heading(p.title,`#${p.id} · ${p.type} · ${p.level}`)+`<section class="card prose"><p>${esc(p.summary)}</p><p><strong>${esc(p.status)}</strong></p><p>${p.hours} estimated effort hours · ${p.courseCount} course${p.courseCount===1?'':'s'} · ${p.sequentialWeeks} suggested weeks if taken sequentially.</p><p>${esc(p.paceNote)}</p><p>Lead faculty: ${esc(p.faculty)}</p><p>Skills: ${esc(p.skills.join(', '))}</p><h2>Access</h2><p>${esc(p.access)}. Price not configured.</p><button class="button" disabled>Checkout unavailable</button><h2>Prerequisite self-check</h2><p>${esc(p.prerequisite)}</p><label><input type="checkbox"> I have reviewed the prerequisites. This does not verify admission eligibility.</label><h2>What's included in the draft</h2>${p.courses.map(c=>`<details><summary>${esc(c.title)} · ${c.hours} effort hours · 10 weeks</summary><p>Shared course ID: ${esc(c.id)}</p><ol>${c.modules.map(m=>`<li><strong>Weeks ${m.weeks.join('–')}: ${esc(m.title)}</strong><p>${esc(m.outcome)}</p></li>`).join('')}</ol><p>Lesson media, assessment banks and executed labs are pending review and production.</p></details>`).join('')}${[32,35,36].includes(p.id)?`<h2>Runnable practice notebooks</h2><p>Standard-library simulations, not Cloud Lab or official autograded assignments. Download and run locally. No learner code is executed by this website.</p>${(p.id===32?['32-1','32-2','32-3','32-4','32-5']:[String(p.id)]).map(k=>`<p><a href="self-paced-practice/${k}-starter.ipynb" download>Download practice ${k} starter</a> <button class="button secondary" data-sp-instructor="${k}">Instructor executed notebook</button></p>`).join('')}<p id="sp-notebook-status" role="status"></p>`:''}<h2>Project and capstone</h2><p>${esc(p.capstone.brief)}</p><p>${esc(p.capstone.review)}</p><ul>${p.capstone.rubric.map(r=>`<li>${esc(r.criterion)}: ${r.points} points</li>`).join('')}</ul><h2>Credential</h2><p>${esc(p.credential)} — proposed requirements, not an issued award.</p><a href="#badge-generator">View badge design generator</a> · <a href="#credentials">Credential previews</a><h2>Transfer proposals</h2><ul>${p.transfer.map(t=>`<li>#${t.to}: ${esc(t.status)} (${esc(t.kind)})</li>`).join('')||'<li>No transfer rule approved.</li>'}</ul><h2>Study planner</h2><p>Save a private planning schedule to your existing pilot course context. This does not enroll you or unlock graded content. Changing the start date recalculates all suggested deadlines.</p><form id="sp-plan" data-program="${p.id}"><label>Start date<input name="start" type="date" required min="2020-01-01" max="2100-01-01" value="${spPlans.find(x=>x.program===p.id)?.start||new Date().toISOString().slice(0,10)}"></label><button class="button">Save or reset suggested schedule</button></form><div id="sp-plan-result" role="status"></div><h2>Quality gates</h2><dl>${Object.entries(p.gates).map(([k,v])=>`<dt><strong>${esc(k)}</strong></dt><dd>${esc(v)}</dd>`).join('')}</dl><p>Framework names describe intended subject coverage only; no affiliation is implied. Tool versions, licenses and textbook mappings still require verification.</p><a href="#self-paced-pathways">See related pathways</a></section>`;}
function spPathways(){return heading('Self-paced pathways','Proposed progression · No automatic credit')+`<section class="card prose"><p><a href="#self-paced">Browse all eleven offerings</a></p><h2>Builder progression</h2><p>${[37,38,32,30,31,28].map(n=>`<a href="${spLink(n)}">#${n}</a>`).join(' → ')} → live #15 or #1</p><h2>Leadership progression</h2><p><a href="${spLink(34)}">#34</a> → #20 → #13/#25. Dependencies and approval remain TBC.</p><p>Quick-start builds: <a href="${spLink(35)}">#35</a> and <a href="${spLink(36)}">#36</a>.</p><h2>Shared course consolidation</h2><p>${esc(spData.consolidation.basis)}</p><ul>${spData.consolidation.pairs.map(p=>`<li>#${p.from} → #${p.to}: ${p.sharedCourses} shared draft courses; ${p.coverageOfTarget}% of target course IDs. Not credit equivalence.</li>`).join('')}</ul><p>${esc(spData.consolidation.legacyOverlap)}</p><p>${esc(spData.consolidation.mergeRetire)}</p><h2>Mapping register</h2><ul>${spData.consolidation.rules.map(r=>`<li>#${r.from} → #${r.to}: ${esc(r.status)}</li>`).join('')}</ul></section>`;}
function spFilter(){const val=id=>document.getElementById(id).value,q=val('sp-search').toLowerCase(),max=Number(val('sp-hours'));const rows=spData.offerings.filter(p=>(p.title+' '+p.summary+' '+p.id).toLowerCase().includes(q)&&(val('sp-type')==='All'||p.type===val('sp-type'))&&(val('sp-level')==='All'||p.level===val('sp-level'))&&(val('sp-coding')==='All'||p.coding===(val('sp-coding')==='Python'))&&(val('sp-skill')==='All'||p.skills.includes(val('sp-skill')))&&(!max||p.hours<=max));document.getElementById('sp-results').innerHTML=rows.map(spCard).join('')||'<p>No matching offerings. Adjust your filters.</p>';document.getElementById('sp-count').textContent=rows.length+' matching offerings';}
const beforeSelfPaced=render;
render=function(){const route=location.hash.slice(1);if(/^program\/(2[89]|3[0-8])$/.test(route)){location.replace('#self-paced/'+route.split('/')[1]);return;}if(!route.startsWith('self-paced')){document.getElementById('sp-structured-data')?.remove();return beforeSelfPaced();}const epoch=++spEpoch;document.getElementById('app').innerHTML=integratedShell('self-paced',heading('Self-paced learning','Loading course outlines…'),model.role);bind();normalizeWorkspace();fetch('data/self-paced.json').then(r=>{if(!r.ok)throw Error('Catalog unavailable');return r.json();}).then(d=>{if(epoch!==spEpoch||location.hash.slice(1)!==route)return;spData=d;const id=Number(route.split('/')[1]),p=d.offerings.find(p=>p.id===id);const body=route==='self-paced-pathways'?spPathways():route==='self-paced'?spHub():p?spProduct(p):heading('Offering not found','Return to the self-paced catalog');document.getElementById('app').innerHTML=integratedShell('self-paced',body,model.role);bind();normalizeWorkspace();document.title=(p?p.title:'Self-paced courses & certificates')+' · Scholarion Academy';spMetadata(p);if(route==='self-paced')spFilter();if(p)workspaceApi('session').then(s=>{workspaceSession=s;if(!s.courses.includes(selectedCourse))selectedCourse=s.courses[0]||'';return workspaceApi('self-paced/list');}).then(r=>{if(epoch!==spEpoch||location.hash.slice(1)!==route)return;spPlans=r.plans;const saved=r.plans.find(x=>x.program===p.id);if(saved)document.querySelector('#sp-plan input[name=start]').value=saved.start;normalizeWorkspace();}).catch(()=>{});}).catch(e=>{if(epoch===spEpoch)document.getElementById('app').textContent=e.message;});};
document.addEventListener('input',e=>{if(['sp-search','sp-type','sp-level','sp-coding','sp-skill','sp-hours'].includes(e.target.id))spFilter();});
document.addEventListener('change',e=>{if(!e.target.dataset.spCompare)return;const n=Number(e.target.dataset.spCompare);if(e.target.checked&&spCompare.size>=3){e.target.checked=false;return toast('Choose up to three offerings.');}e.target.checked?spCompare.add(n):spCompare.delete(n);});
document.addEventListener('click',e=>{if(e.target.id!=='sp-compare')return;const rows=spData.offerings.filter(p=>spCompare.has(p.id));modal('Compare self-paced offerings',rows.length?`<div style="overflow:auto"><table><thead><tr><th>Offering</th><th>Type</th><th>Effort</th><th>Schedule</th><th>Access</th></tr></thead><tbody>${rows.map(p=>`<tr><th>${esc(p.title)}</th><td>${esc(p.type)}</td><td>${p.hours} hours</td><td>${p.courseCount} courses · ${p.sequentialWeeks} weeks sequentially</td><td>Paid sandbox; price pending</td></tr>`).join('')}</tbody></table></div>`:'Select offerings to compare.');});
document.addEventListener('submit',async e=>{if(e.target.id==='sp-recommend'){e.preventDefault();const n={patterns:32,foundations:37,python:30,leaders:34,rag:28}[new FormData(e.target).get('goal')];document.getElementById('sp-recommend-result').innerHTML=`Based on your selected goal: <a href="${spLink(n)}">Explore #${n}</a>. Advisory only; review prerequisites and draft status.`;}if(e.target.id!=='sp-plan')return;e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{workspaceSession=await workspaceApi('session');if(!workspaceSession.courses.includes(selectedCourse))selectedCourse=workspaceSession.courses[0]||'';spPlans=(await workspaceApi('self-paced/list')).plans;const n=Number(e.target.dataset.program);const r=await workspaceApi('self-paced/plan',{program:n,start:new FormData(e.target).get('start'),revision:spPlans.find(p=>p.program===n)?.revision||0});document.getElementById('sp-plan-result').innerHTML=`<p>${esc(r.note)}</p><ul>${r.deadlines.map(x=>`<li>${esc(x.module)}: ${esc(x.suggestedDue)}</li>`).join('')}</ul>`;}catch(err){document.getElementById('sp-plan-result').textContent=err.message+' — Workspace sign-in required for private planning.';}finally{b.disabled=false;}});
render();

document.addEventListener('click',async e=>{const b=e.target.closest('[data-sp-instructor]');if(!b)return;b.disabled=true;try{workspaceSession=await workspaceApi('session');if(!workspaceSession.courses.includes(selectedCourse))selectedCourse=workspaceSession.courses[0]||'';const r=await workspaceApi('self-paced/instructor_notebook',{id:b.dataset.spInstructor});download(r.filename,JSON.stringify(r.notebook,null,2),'application/x-ipynb+json');document.getElementById('sp-notebook-status').textContent='Instructor download recorded. These are practice solutions, not a graded answer key.';}catch(err){document.getElementById('sp-notebook-status').textContent=err.message;}finally{b.disabled=false;}});

function spMetadata(p){document.getElementById('sp-structured-data')?.remove();const el=document.createElement('script');el.id='sp-structured-data';el.type='application/ld+json';const course=x=>({'@type':'Course',name:x.title,description:'Draft curriculum preview. '+x.summary,provider:{'@type':'Organization',name:'Scholarion Academy'}});el.textContent=JSON.stringify(p?{'@context':'https://schema.org',...course(p)}:{'@context':'https://schema.org','@type':'ItemList',itemListElement:spData.offerings.map((x,i)=>({'@type':'ListItem',position:i+1,item:course(x)}))});document.head.appendChild(el);}
